import * as AvatarPrimitive from "@rn-primitives/avatar";
import type { ComponentProps } from "react";
import { TextClassContext } from "../../lib/text-context.js";
import { cn } from "../../lib/utils.js";

/** Props for {@link Avatar}. */
export type AvatarProps = ComponentProps<typeof AvatarPrimitive.Root>;

/**
 * A circular user image with a fallback for when the image is missing or
 * still loading.
 *
 * `alt` is required by the primitive and is what assistive tech announces,
 * so it belongs on the root rather than on the image.
 * @param props - {@link AvatarProps}
 * @returns The avatar root
 * @example
 * ```tsx
 * <Avatar alt="Ada Lovelace's profile picture">
 *   <AvatarImage source={{ uri: user.avatarUrl }} />
 *   <AvatarFallback><Text>AL</Text></AvatarFallback>
 * </Avatar>
 * ```
 */
export function Avatar({ className, ...props }: AvatarProps) {
	return (
		<AvatarPrimitive.Root
			className={cn("relative size-10 shrink-0 overflow-hidden rounded-full", className)}
			{...props}
		/>
	);
}

/** Props for {@link AvatarImage}. */
export type AvatarImageProps = ComponentProps<typeof AvatarPrimitive.Image>;

/**
 * The avatar's image. Renders nothing until the source loads, which is what
 * lets the fallback show through.
 * @param props - {@link AvatarImageProps}
 * @returns The avatar image
 */
export function AvatarImage({ className, ...props }: AvatarImageProps) {
	return <AvatarPrimitive.Image className={cn("aspect-square size-full", className)} {...props} />;
}

/** Props for {@link AvatarFallback}. */
export type AvatarFallbackProps = ComponentProps<typeof AvatarPrimitive.Fallback>;

/**
 * Shown while the image loads or when it fails. Holds initials or an icon.
 * @param props - {@link AvatarFallbackProps}
 * @returns The avatar fallback
 */
export function AvatarFallback({ className, ...props }: AvatarFallbackProps) {
	return (
		<TextClassContext.Provider value="text-sm font-medium text-muted-foreground">
			<AvatarPrimitive.Fallback
				className={cn(
					"size-full flex-row items-center justify-center rounded-full bg-muted",
					className,
				)}
				{...props}
			/>
		</TextClassContext.Provider>
	);
}

import { createContext, useContext } from "react";

/**
 * Class names a parent wants applied to the `<Text>` elements inside it.
 *
 * React Native text does not inherit colour or size from its container the
 * way DOM text does, so a `Button` cannot make its label
 * `text-primary-foreground` by styling itself. Instead it provides that
 * class here and `Text` reads it. Same pattern React Native Reusables
 * uses; kept as a tiny shared module so every component agrees on it.
 */
export const TextClassContext = createContext<string | undefined>(undefined);

/**
 * Read the class names the nearest text-styling ancestor provided.
 * @returns The inherited class string, or undefined outside any provider
 */
export function useTextClass(): string | undefined {
	return useContext(TextClassContext);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind-aware conflict resolution.
 *
 * Deliberately a copy of the web helper rather than an import from
 * `@hex-core/components`: that package is React DOM, and `hex add` ships
 * this file into the consumer's project alongside each component anyway.
 * NativeWind's platform prefixes (`ios:`, `android:`, `native:`) are
 * unknown to tailwind-merge and pass through untouched.
 * @param inputs - Class values (strings, arrays, conditionals) to merge
 * @returns The merged class string with later Tailwind utilities winning
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
